guard let url = Bundle.main.url(forResource: "EusoTrip_Splash_iOS_3s_1080x1920", withExtension: "mp4") else { return }
let player = AVPlayer(url: url); player.isMuted = true
let layer = AVPlayerLayer(player: player); layer.videoGravity = .resizeAspectFill; layer.frame = view.bounds
view.layer.addSublayer(layer)
NotificationCenter.default.addObserver(forName: .AVPlayerItemDidPlayToEndTime, object: player.currentItem, queue: .main) { _ in self.finishSplash() }
player.play()
